async cadastrarLoja(d){
  if(!d.aceite)throw new Error('É preciso aceitar os Termos de Uso e a Política de Privacidade.');
  if(!d.senha||String(d.senha).length<6)throw new Error('A senha deve ter pelo menos 6 caracteres.');
  if(!d.logo)throw new Error('Envie a logo da loja.');
  const em=nt(d.whatsapp)+EM;let uid;const s=await sb.auth.signUp({email:em,password:d.senha});
  if(s.error&&!/already|registered|exists/i.test(String(s.error.message)))throw new Error(/password/i.test(s.error.message)?'Senha não aceita. Use pelo menos 6 caracteres, de preferência com letras e números.':/rate|too many|limit|429/i.test(s.error.message+s.error.status)?'Muitas tentativas seguidas. Aguarde alguns minutos e tente de novo.':'Não foi possível criar o acesso: '+s.error.message);
  if(s.error||!s.data.session){const r=await sb.auth.signInWithPassword({email:em,password:d.senha});if(r.error)throw new Error('Este WhatsApp já está cadastrado. Entre com a senha dele ou peça uma nova à administração.');uid=r.data.user.id}else uid=s.data.user.id;
  const ex=(await sb.from('lojas').select('id,status').eq('owner_id',uid).maybeSingle()).data;
  if(ex&&ex.status!=='recusada'){await sb.auth.signOut();throw new Error('Este WhatsApp já está cadastrado.')}
  try{const logo=await up('logos',uid,d.logo,'logo-'+Date.now());
   const row={nome:d.nome,responsavel:d.responsavel,sobrenome:d.sobrenome,whatsapp:nt(d.whatsapp),endereco:adrTxt({rua:d.rua,num:d.num,comp:d.comp}),rua:d.rua,numero:d.num,complemento:d.comp||null,referencia:d.ref,bairro:d.bairro,cidade:d.cidade,categoria:d.categoria||null,horario:d.horario||'{}',logo:logo,aceite_em:new Date().toISOString(),email:d.email};
   const w=ex?await sb.from('lojas').update({...row,status:'pendente'}).eq('id',ex.id):await sb.from('lojas').insert({...row,owner_id:uid,status:'pendente'});if(w.error)throw new Error(/row-level security/i.test(w.error.message)?'O cadastro não foi aceito pelo servidor (permissão). Tente de novo ou fale com a administração.':/lojas_email_uq|duplicate key/i.test(w.error.message)?'Este e-mail já está cadastrado. Use outro e-mail.':w.error.message)}
  finally{await sb.auth.signOut()}
  return true},
