 $('cpLp').style.display=q==='dividido'?'':'none';$('cpCp').style.display=r==='tabela'?'none':'';$('cpCpT').textContent=r==='extra'?'Extra sobre a tabela':'Comissão fixa';
 const P=num($('cpsP').value)||0,pct=num(fd.get('valor')||0)||0,teto=num(fd.get('teto')||'')||0,cp=num(fd.get('com_pct')||0)||0,s=q==='valeshop'?0:q==='dividido'?Math.min(100,Math.max(0,num(fd.get('loja_pct')||50)||0))/100:1;
